code_templates.process_health_check:
def is_process_healthy(pid):
    try:
        proc = psutil.Process(pid)
        cpu = proc.cpu_percent(interval=1.0)
        status = proc.status()

        if cpu == 0.0 and status in ['stopped', 'zombie']:
            return False
        return True
    except:
        return False

